Here's a modern MSTest data-driven test class for your `PriceCalculator`:

```csharp
using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator = new();

    // --- CalculateTotal: DataRow for simple inline cases ---

    [TestMethod]
    [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
    [DataRow(10.00, 5, 0.0, 50.00, DisplayName = "Multiple items, no tax")]
    [DataRow(10.00, 2, 0.10, 22.00, DisplayName = "Two items, 10% tax")]
    [DataRow(0.00, 3, 0.25, 0.00, DisplayName = "Zero price")]
    [DataRow(99.99, 1, 0.07, 106.99, DisplayName = "Typical tax rate")]
    public void CalculateTotal_WithValidInputs_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, Math.Round(result, 2));
    }

    // --- ApplyDiscount: DynamicData with ValueTuples for type safety ---

    [TestMethod]
    [DynamicData(nameof(DiscountTestData))]
    public void ApplyDiscount_WithValidInputs_ReturnsExpected(
        decimal price, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal price, decimal discountPercent, decimal expected)> DiscountTestData =>
    [
        (100m, 10m, 90m),
        (200m, 25m, 150m),
        (50m, 0m, 50m),
        (80m, 100m, 0m),
        (99.99m, 50m, 49.995m),
    ];

    // --- Exception cases ---

    [TestMethod]
    [DataRow(-1.0, 1, 0.1, DisplayName = "Negative price throws")]
    public void CalculateTotal_NegativePrice_Throws(double unitPrice, int qty, double tax)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, qty, (decimal)tax));
    }

    [TestMethod]
    [DataRow(10.0, -1, 0.1, DisplayName = "Negative quantity throws")]
    public void CalculateTotal_NegativeQuantity_Throws(double unitPrice, int qty, double tax)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, qty, (decimal)tax));
    }

    [TestMethod]
    [DataRow(-1.0)]
    [DataRow(101.0)]
    public void ApplyDiscount_InvalidPercent_Throws(double discountPercent)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, (decimal)discountPercent));
    }
}
```

**Key patterns used:**

| Technique | Why |
|-----------|-----|
| `[DataRow]` | Simple inline data; note `double` params (DataRow can't hold `decimal` literals) cast to `decimal` inside the method |
| `[DynamicData]` with ValueTuples | Complex/`decimal` data with full type safety (MSTest 3.7+) |
| `Assert.ThrowsExactly<T>` | Modern exception testing (replaces `[ExpectedException]`) |
| `sealed` class | Best practice for test classes |
| `DisplayName` | Readable test names in Test Explorer |

For `DataRow`, remember that C# attributes don't support `decimal` literals — use `double` and cast inside the method. For precise decimal test data, prefer `DynamicData` with ValueTuples as shown above.
